import assert from 'node:assert/strict';
import { mergeConfig } from '../src/config.js';

function freeze(value) {
  if (value && typeof value === 'object') {
    for (const key of Reflect.ownKeys(value)) freeze(value[key]);
    Object.freeze(value);
  }
  return value;
}

const defaults = freeze({
  server: { host: 'localhost', port: 8080, tls: { enabled: true, cert: { path: 'old', format: 'pem' } } },
  logging: { level: 'info', sinks: { console: true, file: false } },
  untouched: { value: 42 }
});
const overrides = freeze({
  server: { port: 9090, tls: { cert: { path: 'new' } } },
  logging: { sinks: { file: true, remote: false } },
  extra: { nested: { value: 'added' } }
});
const beforeDefaults = JSON.stringify(defaults);
const beforeOverrides = JSON.stringify(overrides);
assert.deepEqual(mergeConfig(defaults, overrides), {
  server: { host: 'localhost', port: 9090, tls: { enabled: true, cert: { path: 'new', format: 'pem' } } },
  logging: { level: 'info', sinks: { console: true, file: true, remote: false } },
  untouched: { value: 42 },
  extra: { nested: { value: 'added' } }
});
assert.equal(JSON.stringify(defaults), beforeDefaults);
assert.equal(JSON.stringify(overrides), beforeOverrides);
assert.deepEqual(mergeConfig({ a: { b: { c: 1 } } }, { a: {} }), { a: { b: { c: 1 } } });
assert.deepEqual(mergeConfig({ a: { b: null, keep: 1 } }, { a: { b: { c: 2 } } }), { a: { b: { c: 2 }, keep: 1 } });

// Exercise depth beyond a handful of hard-coded levels.
let left = { keep: 'leaf', change: 0 };
let right = { change: 1 };
let expected = { keep: 'leaf', change: 1 };
for (let depth = 0; depth < 40; depth++) {
  left = { keep: depth, child: left };
  right = { child: right };
  expected = { keep: depth, child: expected };
}
assert.deepEqual(mergeConfig(freeze(left), freeze(right)), expected);

// Null-prototype records are also plain configuration objects.
const record = Object.assign(Object.create(null), { keep: 1, change: 2 });
const patch = Object.assign(Object.create(null), { change: 3 });
const result = mergeConfig({ record }, { record: patch });
assert.equal(result.record.keep, 1);
assert.equal(result.record.change, 3);
assert.equal(record.change, 2);
assert.equal(patch.change, 3);

import assert from 'node:assert/strict';
import { mergeConfig } from '../src/config.js';

assert.deepEqual(mergeConfig({ level: 'info', color: true }, { level: 'debug', file: 'app.log' }), { level: 'debug', color: true, file: 'app.log' });
assert.deepEqual(mergeConfig({}, {}), {});
assert.deepEqual(mergeConfig({ tags: ['a', 'b'] }, { tags: ['c'] }), { tags: ['c'] });

class Instance { constructor() { this.value = 3; } }
const replacements = [null, undefined, false, 0, 12, '', 'text', [9], new Date(0), /abc/, new Map([['a', 1]]), new Instance(), () => 1];
for (const value of replacements) {
  const defaults = Object.freeze({ slot: Object.freeze({ keep: 1 }) });
  const overrides = Object.freeze({ slot: value });
  const result = mergeConfig(defaults, overrides);
  assert.ok(Object.hasOwn(result, 'slot'));
  assert.strictEqual(result.slot, value, 'non-plain overrides replace the value whole');
  assert.deepEqual(defaults.slot, { keep: 1 });
  assert.strictEqual(overrides.slot, value);
}

// A plain override must not inherit keys from a non-plain default.
for (const value of [null, undefined, 1, 'abc', [1, 2], new Instance()]) {
  assert.deepEqual(mergeConfig({ slot: value }, { slot: { fresh: true } }), { slot: { fresh: true } });
}

const shared = Object.freeze({ value: 1 });
const defaults = Object.freeze({ retained: shared, replaced: Object.freeze([1, 2]) });
const overrides = Object.freeze({ replaced: Object.freeze([3]), added: Object.freeze({ x: 1 }) });
assert.deepEqual(mergeConfig(defaults, overrides), { retained: { value: 1 }, replaced: [3], added: { x: 1 } });
assert.deepEqual(defaults, { retained: { value: 1 }, replaced: [1, 2] });
assert.deepEqual(overrides, { replaced: [3], added: { x: 1 } });

// Preserve spread's own-enumerable-key behavior, including explicit undefined.
const inherited = Object.create({ inherited: 99 });
inherited.own = 1;
Object.defineProperty(inherited, 'hidden', { value: 2 });
const symbol = Symbol('option');
assert.deepEqual(mergeConfig(inherited, { own: undefined, [symbol]: 3 }), { own: undefined, [symbol]: 3 });
const special = JSON.parse('{"__proto__":{"safe":true},"constructor":7,"prototype":8}');
const specialResult = mergeConfig({}, special);
assert.ok(Object.hasOwn(specialResult, '__proto__'));
assert.deepEqual(specialResult, special);
assert.equal(Object.getPrototypeOf(specialResult), Object.prototype);
